/opt/local/libexec/cmake-bootstrap/bin/cmake -G "Unix Makefiles" -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX="/opt/local/libexec/darwin-xtools" -DCMAKE_INSTALL_NAME_DIR="/opt/local/libexec/darwin-xtools/lib" -DCMAKE_SYSTEM_PREFIX_PATH="/opt/local;/opt/local/libexec/darwin-xtools;/usr" -DCMAKE_C_COMPILER="/usr/bin/clang" -DCMAKE_CXX_COMPILER="/usr/bin/clang++" -DCMAKE_VERBOSE_MAKEFILE=ON -DCMAKE_COLOR_MAKEFILE=ON -DCMAKE_FIND_FRAMEWORK=LAST -DCMAKE_EXPORT_COMPILE_COMMANDS=ON -DCMAKE_MAKE_PROGRAM=make -DCMAKE_MODULE_PATH="/opt/local/share/cmake/Modules" -DCMAKE_PREFIX_PATH="/opt/local/share/cmake/Modules" -DCMAKE_BUILD_WITH_INSTALL_RPATH:BOOL=ON -DCMAKE_INSTALL_RPATH="/opt/local/lib;/opt/local/libexec/darwin-xtools/lib" -Wno-dev -DCCTOOLS_LD_CLASSIC=OFF -DXTOOLS_LIBYAML_PATH=/Users/ericgallager/Documents/GitHub/darwin-xtools/libyaml  -DXTOOLS_USE_TAPILITE=ON -DXTOOLS_HOST_IS_64B=ON -DCMAKE_OSX_ARCHITECTURES="x86_64" -DCMAKE_OSX_DEPLOYMENT_TARGET="26.0" -DCMAKE_OSX_SYSROOT="/Library/Developer/CommandLineTools/SDKs/MacOSX26.sdk" ..
